reference_solution:
def maximize_number_by_inserting_digit(n, x):
    digit = str(x)
    if n[0] == "-":
        position = 1
        while position < len(n) and n[position] <= digit:
            position += 1
    else:
        position = 0
        while position < len(n) and n[position] >= digit:
            position += 1
    return n[:position] + digit + n[position:]

